  always @(posedge clk or posedge reset)
    begin : AXIS_rnd_master_32bit_1_process
      if (reset == 1'b1) begin
        state_reg <= 2'b00;
        AXIS_counter <= 32'b00000000000000000000000000000000;
        some_length <= 11'b00001000000;
        counter <= 11'b00000000000;
        p_data <= 32'b00000000000000000000000000000000;
        p_last <= 1'b0;
