  always @(AXIS_counter, channel_up, corrupt_data_reg, corrupt_data_reg_d, counter,
       enable, lane_up, m_axis_tready, p_data, p_keep, p_last, p_valid, rnd,
       s_data, s_keep, s_last, s_valid, some_length, state_reg) begin
    c = 11'b00000000000;
    c_0 = 11'b00000000000;
    c_1 = 5'b00000;
    t_2 = 3'b000;
    a = 11'b00000000000;
    t_3 = 8'd0;
    a_0 = 11'b00000000000;
    p_valid_temp = p_valid;
    s_valid_temp = s_valid;
    counter_next = counter;
    some_length_next = some_length;
    AXIS_counter_next = AXIS_counter;
