    // ---------------- Регистры FSM ------------------
    // ---------------- Primary stage (видна на AXIS) --
    // ---------------- Skid stage (резерв) -----------
    // ---------------- Выходы ------------------------
    corrupt_data_out = corrupt_data_reg && ( ! corrupt_data_reg_d);
    corrupt_data_reg_d_next = corrupt_data_reg;
    // ---------------- Skid-контракт -----------------
    // Можно принять ещё одно слово, пока обе ступени не заняты.
    t_0 = p_valid && s_valid;
    in_ready =  ! t_0;
    // Факт передачи beat'а получателем (только по primary).
    accept = p_valid && m_axis_tready;
    // ---------------- Локальные «push» из FSM -------
    push = 1'b0;
    // push_data = fi(0, AXIS_nt, fm);
    push_data = AXIS_counter;
    c_r = 4'b1111;
    push_last = 1'b0;
    // ---------------- FSM ---------------
    // switch (bitsliceget(D_FIFO_rd_data,AXIS_nt.WordLength+2,AXIS_nt.WordLength+1))
    //     case 0
    //         rd_keep = fi(bin2dec('0001'),0,p_keep.WordLength,0,fm);
    //     case 1
    //         rd_keep = fi(bin2dec('0011'),0,p_keep.WordLength,0,fm);
    //     case 2
    //         rd_keep = fi(bin2dec('0111'),0,p_keep.WordLength,0,fm);
    //     case 3
    //         rd_keep = fi(bin2dec('1111'),0,p_keep.WordLength,0,fm);
    //     otherwise
    //         rd_keep = fi(0,0,4,0,fm);
    // end
    some_length_cut = some_length[3:0];
    counter_cut = counter[3:0];
    last_m_axis_count = some_length_cut - counter_cut;
    t_1 = channel_up && lane_up;
    if ( ! t_1) begin
      state_reg_next = 2'b00;
      counter_next = 11'b00000000000;
      some_length_next = 11'b00000111100;
      AXIS_counter_next = 32'b00000000000000000000000000000000;
      p_valid_temp = 1'b0;
      s_valid_temp = 1'b0;
    end
    else begin
      case ( state_reg)
        2'b00 :
          begin
            if (enable) begin
              if (rnd < 16'd60) begin
