              end
              else if (rnd > 16'd1514) begin
                // some_length = fi(LENGTH_MAX_LIMIT, 0, some_length.WordLength, 0, fm);
                a = rnd[10:0];
                c = a >> 8'd1;
                some_length_next = c;
