                end
                state_reg_next = 2'b01;
                counter_next = 11'b00000000000;
              end
            end
            else begin
              state_reg_next = 2'b10;
            end
          end
      endcase
    end
    // ---------------- Обновление skid-buffer --------
    if (accept && push) begin
      // В этот такт primary отдаётся получателю, сразу кладём новое слово.
