      if (s_valid_temp) begin
        p_data_next = s_data;
        p_last_next = s_last;
        p_keep_next = s_keep;
        p_valid_temp = 1'b1;
        s_valid_temp = 1'b0;
      end
      else begin
        p_valid_temp = 1'b0;
      end
    end
    else if (( ! accept) && push) begin
      // Получатель не принимает, а мы уже подтвердили rd_en.
      // Если primary занят — прячем новое слово в skid; иначе — в primary.
      if (p_valid_temp) begin
        s_data_next = push_data;
        s_last_next = push_last;
        s_keep_next = c_r;
        s_valid_temp = 1'b1;
      end
      else begin
        p_data_next = push_data;
        p_last_next = push_last;
        p_keep_next = c_r;
        p_valid_temp = 1'b1;
      end
    end
    // (~accept && ~push) — держим всё как есть.
    m_axis_tdata_1 = p_data;
    m_axis_tvalid_1 = p_valid;
    m_axis_tlast_1 = p_last;
    m_axis_tkeep_1 = p_keep;
    some_length_out_1 = some_length;
    p_valid_next = p_valid_temp;
    s_valid_next = s_valid_temp;
